function validate(input) {
  const [{ Matches = [] }] = input;
  const seen = new Set();
  for (const [player, day, result] of Matches) {
    if (player === null || day === null || result === null) return 'Matches rows may not contain null.';
    if (!['Win', 'Draw', 'Lose'].includes(result)) return `result must be Win, Draw or Lose, not ${result}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `match_day ${day} is not a date.`;
    const key = `${player}|${day}`;
    if (seen.has(key)) return `Player ${player} plays twice on ${day}.`;
    seen.add(key);
  }
  return null;
}

