function generate(rand, size) {
  const day = n => new Date(Date.UTC(2022, 0, 1 + n)).toISOString().slice(0, 10);
  const pick = () => { const r = rand(); return r < 0.6 ? 'Win' : r < 0.8 ? 'Draw' : 'Lose'; };
  const Matches = [];
  if (size === 'small') {
    // A few players share a small pool of days, so partitions interleave and runs of wins are common.
    const count = Math.floor(rand() * 9), seen = new Set();
    for (let i = 0; i < count; i++) {
      const player = 1 + Math.floor(rand() * 3), d = day(Math.floor(rand() * 10));
      if (seen.has(`${player}|${d}`)) continue;
      seen.add(`${player}|${d}`);
      Matches.push([player, d, pick()]);
    }
  } else {
    for (let player = 1; player <= 40; player++) {
      let n = Math.floor(rand() * 5);
      for (let i = 0; i < 50; i++) { n += 1 + Math.floor(rand() * 3); Matches.push([player, day(n), pick()]); }
    }
    for (let i = Matches.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Matches[i], Matches[j]] = [Matches[j], Matches[i]]; }
  }
  return [{ Matches }];
}
